ht:90px}.formation-choice:hover{border-color:#ffb84d}.game-screen .match-stats{padding:8px;font-size:11px;margin:8px 0}.finish-panel{margin:8px 0}.finish-panel h2{margin:0 0 8px}.finish-panel .btn{margin:4px}
