/* V1.4 – volle Tischbreite: die Bedienung liegt auf der freien Tischfläche. */
.table-with-actions{display:block}
.matchstack{max-width:580px;width:100%;padding-bottom:4px}
.game-actions{position:absolute;left:7px;top:50%;transform:translateY(-50%);z-index:5;display:flex;flex-direction:column;gap:7px;margin:0}
.game-actions .action-icon{min-width:38px;min-height:38px;padding:6px 4px;font-size:19px;background:#183a40d9;border:1px solid #6e9b9d99;color:white;box-shadow:0 2px 6px #0004}
.matchstack .cupfield{height:clamp(175px,28vh,235px)}
.matchstack .cups{transform:scale(.78)}
.matchstack .board-top{transform:scale(.78) rotate(180deg)}
.matchstack .cup{width:50px;height:50px}
@media(max-width:650px){
 .matchstack{border-width:5px}
 .matchstack .cupfield{height:clamp(155px,25vh,205px)}
 .matchstack .cups{transform:scale(.67)}
 .matchstack .board-top{transform:scale(.67) rotate(180deg)}
