/* V1.5: Spielfeld aufräumen, grosse Becher mit sichtbarem Abstand */
.game-screen{max-width:760px}
.game-screen .match-stats{display:none}
.matchstack{max-width:700px}
.matchstack .cupfield{height:clamp(188px,29vh,258px)}
.matchstack .cups{transform:scale(.89)}
.matchstack .board-top{transform:scale(.89) rotate(180deg)}
.matchstack .cup{width:47px;height:47px;border-width:4px;box-shadow:inset 0 0 0 6px #dc714d,0 4px 8px #0005}
.matchstack .cup.red{box-shadow:inset 0 0 0 6px #c72f41,0 4px 8px #0005}
.matchstack .cup.blue{box-shadow:inset 0 0 0 6px #2373d4,0 4px 8px #0005}
.matchstack .cup.candidate{box-shadow:0 0 0 5px #f9c44b99}
.rerack-backdrop{position:fixed;inset:0;z-index:80;background:#07151cbb;display:grid;place-items:center;padding:16px;overflow:auto}
.rerack-backdrop .rerack-panel{width:min(560px,100%);max-height:90dvh;overflow:auto;margin:0;padding:18px;background:#203640;border:2px solid #6c959b;box-shadow:0 20px 60px #000a}
.rerack-backdrop .rerack-panel h3{font-size:23px;text-align:center;margin:0 0 15px}
.rerack-backdrop .formation-grid{grid-template-columns:repeat(auto-fit,minmax(110px,1fr));gap:12px}
.rerack-backdrop .formation-choice{min-height:105px}
.rerack-backdrop .formation-choice svg{height:110px}
.trick-flash{position:fixed;inset:0;z-index:90;display:grid;place-items:center;pointer-events:none;background:#06151e80;animation:flashEnter .4s ease-out both}
.trick-flash-inner{text-align:center;padding:24px 20px;width:min(95vw,580px);border-radius:24px;background:linear-gradient(135deg,#2a1c42ee,#53351bee);border:3px solid #ffd06a;box-shadow:0 0 50px #ffc64e77;animation:trickGlow 1.1s ease-in-out infinite alternate}
.trick-flash-title{font-size:clamp(34px,9vw,66px);font-weight:1000;color:#ffe18b;text-shadow:0 0 22px #ffb84d;letter-spacing:1px}
.trick-flash-task{font-size:clamp(23px,6vw,39px);font-weight:900;color:white;margin-top:14px}
@keyframes flashEnter{from{opacity:0;transform:scale(.92)}to{opacity:1;transform:scale(1)}}
@keyframes trickGlow{from{box-shadow:0 0 25px #ffbd4877}to{box-shadow:0 0 65px #ffd86ccc}}
@media(max-width:650px){
 .game-screen .match-notice{font-size:12px}
 .matchstack .cupfield{height:clamp(163px,26vh,210px)}
 .matchstack .cups{transform:scale(.74)}
 .matchstack .board-top{transform:scale(.74) rotate(180deg)}
 .matchstack .cup{width:47px;height:47px}
 .rerack-backdrop .formation-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
}
