@media(max-width:380px){.trick-choice-modal{padding:12px}.trick-choice-grid{gap:6px}.trick-choice-grid .btn{font-size:13px;min-height:46px}}
/* V3.0 – kompakte Statistik auf dem Smartphone */
.compact-stats{width:100%;table-layout:fixed}
.compact-stats th:first-child,.compact-stats td:first-child{width:43%;text-align:left}
.compact-stats th:not(:first-child),.compact-stats td:not(:first-child){text-align:center}
.compact-stats td,.compact-stats th{padding:12px 6px}
.compact-stats td .btn{max-width:100%;white-space:normal;overflow-wrap:anywhere;text-align:left;padding:10px 8px;font-size:clamp(11px,3vw,14px)}
@media(max-width:440px){.compact-stats th,.compact-stats td{font-size:12px;padding:9px 3px}.compact-stats td .btn{font-size:12px}}

/* V3.1: kompakte Startseite, grosse gut erreichbare 3D-Becher */
.welcome-mini{display:flex;align-items:center;gap:12px;margin:0 0 18px;padding:10px 2px;font-size:clamp(16px,4vw,20px)}
.welcome-mini .avatar{width:38px;height:38px}
/* Dunkler, breiter Spieltisch ohne Mittelspalt. */
.game-screen{max-width:780px}
.matchstack{max-width:740px;padding:7px 4px;border:5px solid #546a7b;border-radius:24px;background:repeating-linear-gradient(143deg,rgba(72,112,143,.12) 0 13px,transparent 13px 31px),linear-gradient(145deg,#152b43,#101d33 55%,#1a344a);box-shadow:inset 0 0 0 2px #a4b4c066,0 14px 34px #0009}
.matchstack .cupfield{height:clamp(245px,34vh,300px);overflow:visible}
.matchstack .cups{transform:scale(1.10)}
.matchstack .board-top{transform:scale(1.10) rotate(180deg)}
.matchstack .cup{width:53px;height:60px;border:0;border-radius:0;background:transparent!important;box-shadow:none!important;overflow:visible;isolation:isolate;touch-action:manipulation;filter:drop-shadow(0 6px 4px #0008)}
.matchstack .cup::before{content:"";position:absolute;z-index:0;left:3px;right:3px;top:10px;bottom:2px;clip-path:polygon(0 0,100% 0,85% 100%,15% 100%);background:linear-gradient(90deg,#6f1529,#ed5665 26%,#d52243 64%,#79172b);border-radius:0 0 9px 9px}
