/* V3.3 – Spielfeld nach der Lieblingsskizze: zwei vollständige Pyramiden. */
.shell.shell-game{padding:0!important;max-width:100%;}
.shell-game .game-screen{width:100%;max-width:700px;margin:0 auto;}
.game-screen .table-with-actions{display:block!important;}
.game-screen .matchstack{box-sizing:border-box;position:relative;display:flex;flex-direction:column;gap:0;width:100%;max-width:700px;margin:0 auto;padding:0 4px;border:4px solid #50677b;border-radius:0;background:repeating-linear-gradient(145deg,#172b40 0 36px,#132438 36px 74px);box-shadow:inset 0 0 0 2px #92abc233,0 8px 25px #0007;overflow:hidden;}
.game-screen .matchstack .cupfield{height:clamp(235px,37dvh,350px)!important;min-height:0!important;flex:none;background:transparent;border:0;margin:0;padding:0;display:flex;align-items:center;justify-content:center;overflow:visible;}
.game-screen .matchstack .cups{width:290px;height:230px;max-width:none;flex-shrink:0;transform:scale(var(--cup-scale,1.07))!important;transform-origin:center;}
.game-screen .matchstack .board-top{transform:scale(var(--cup-scale,1.07)) rotate(180deg)!important;}
.game-screen .matchstack .board-top .cup{transform:translate(-50%,-50%) rotate(180deg)!important;}
.game-screen .matchstack .board-bottom .cup{transform:translate(-50%,-50%)!important;}
.game-screen .matchstack .cup{box-sizing:border-box;position:absolute;width:49px!important;height:67px!important;border:0!important;border-radius:0!important;background:transparent!important;box-shadow:none!important;filter:drop-shadow(0 5px 4px #0008);overflow:visible;opacity:1!important;touch-action:manipulation;transition:filter .15s;}
.game-screen .matchstack .cup::before{content:"";position:absolute;top:13px;bottom:1px;left:3px;right:3px;z-index:0;clip-path:polygon(0 0,100% 0,84% 100%,16% 100%);border-radius:0 0 9px 9px;background:linear-gradient(90deg,#651323,#e94e62 27%,#ce2740 69%,#751728);}
.game-screen .matchstack .cup::after{content:"";position:absolute;top:2px;left:0;right:0;height:23px;z-index:1;border:5px solid #ffd5d8;border-radius:50%;background:radial-gradient(ellipse at center,#64111e 0 56%,#a52235 65%,#e84c63 100%);box-shadow:0 2px 3px #0007,inset 0 1px 3px #0008;}
.game-screen .matchstack .cup.blue::before{background:linear-gradient(90deg,#0b3474,#50a7ff 28%,#1e75d8 67%,#0b377e);}
.game-screen .matchstack .cup.blue::after{border-color:#d6efff;background:radial-gradient(ellipse at center,#0d397a 0 56%,#2065b6 65%,#68b6ff 100%);}
.game-screen .matchstack .cup.candidate{filter:drop-shadow(0 0 9px #ffcf54) drop-shadow(0 5px 4px #0008);}
.game-screen .matchstack .cup.pending{filter:drop-shadow(0 0 9px #6af9f1);}
.game-screen .matchstack .cup:focus-visible{outline:3px solid #fff;outline-offset:4px;}
.game-screen .table-side-label{z-index:4;position:relative;display:flex;align-items:center;gap:9px;justify-content:flex-start;min-height:61px;padding:8px 64px 8px 16px;background:transparent!important;border:0!important;font-size:clamp(16px,4.2vw,22px);text-align:left;color:#e9f3fa;text-shadow:0 2px 6px #000a;}
.game-screen .table-side-label .avatar{width:43px;height:43px;flex:none;}
.game-screen .table-side-label .player-label{min-width:0;display:flex;flex-wrap:wrap;align-items:baseline;gap:4px;}
