.game-screen .game-actions .action-icon:nth-child(3){border-color:#d1a0ff;box-shadow:0 0 12px #c287ff66;}
.game-screen .game-actions .action-icon:active{filter:brightness(1.5);}
.game-screen .game-exit{position:absolute;z-index:31;right:10px;top:10px;width:44px;height:44px;border:2px solid #7291a9;border-radius:50%;background:#243a50de;color:white;font-size:27px;}
.game-screen .fullscreen-status{position:absolute;z-index:35;left:50%;top:50%;transform:translate(-50%,-50%);width:max-content;max-width:72%;padding:7px 11px;border-radius:24px;background:#081a2cdd;color:#e9f3fa;text-align:center;font-size:12px;pointer-events:none;}
