@media(max-width:650px){.game-screen .matchstack{--cup-scale:clamp(.82,calc((100vw - 24px)/320px),1.15);}.game-screen .table-side-label{min-height:57px;padding-left:12px;}.game-screen .matchstack .cupfield{height:clamp(220px,36dvh,330px)!important;}}
@media(max-width:360px){.game-screen .matchstack{--cup-scale:.85;}.game-screen .game-actions{left:3px;}}
@media(max-height:700px) and (max-width:650px){.game-screen .matchstack .cupfield{height:clamp(195px,34dvh,260px)!important;}}

/* V3.5: Aufrechte rote Becher, aktive Namen und Wurftext als eine Neonzeile. */
.game-screen .matchstack .board-top .cup{transform:translate(-50%,-50%)!important;}
.game-screen .table-side-label .player-label{display:flex;align-items:center;min-width:0;flex:1;}
.game-screen .table-side-label .player-status{display:inline-flex;align-items:baseline;gap:5px;min-width:0;max-width:100%;white-space:nowrap;}
.game-screen .table-side-label .player-status strong{flex:0 1 auto;min-width:0;overflow:hidden;text-overflow:ellipsis;}
.game-screen .table-side-label .throw-count{display:inline;flex:none;font-weight:800;font-size:clamp(12px,3.2vw,17px);color:inherit;}
.game-screen .table-side-label.player-top.is-active .player-status,
.game-screen .table-side-label.player-top.is-active .throw-count{color:#ff8ca1!important;text-shadow:0 0 7px #ff426c,0 0 17px #ff426c,0 0 28px #ff426c88;}
.game-screen .table-side-label.player-bottom.is-active .player-status,
.game-screen .table-side-label.player-bottom.is-active .throw-count{color:#7dc8ff!important;text-shadow:0 0 7px #319dff,0 0 17px #319dff,0 0 28px #319dff88;}
.game-screen .table-side-label.is-active .player-status strong{color:inherit;text-shadow:inherit;}
.game-screen .table-side-label:not(.is-active) .player-status{color:#e9f3fa;text-shadow:0 2px 6px #000a;}
@media(max-width:390px){.game-screen .table-side-label .player-status{gap:3px}.game-screen .table-side-label strong{font-size:clamp(14px,4vw,18px)}.game-screen .table-side-label .throw-count{font-size:clamp(11px,3vw,14px)}}

/* V3.6 – volle Smartphone-Hoehe, aufrechte Becher, einheitlicher Neon-Status. */
.game-screen .matchstack{height:calc(100dvh - 8px);min-height:620px;max-height:none;--cup-scale:1.22;}
.game-screen .matchstack .cupfield{height:auto!important;min-height:0!important;flex:1 1 0;overflow:visible;}
/* Die obere Pyramide wird durch gespiegelte Y-Koordinaten gezeichnet, NICHT durch Drehen der Becher. */
.game-screen .matchstack .board-top{transform:scale(var(--cup-scale))!important;}
.game-screen .matchstack .board-top .cup{transform:translate(-50%,-50%)!important;}
.game-screen .table-side-label{flex:none;min-height:68px;}
.game-screen .table-side-label.is-active .avatar{border:3px solid #82caff;box-shadow:0 0 0 2px #78caff55,0 0 14px #44b4ff,0 0 26px #44b4ff66;}
.game-screen .table-side-label.player-top.is-active .avatar{border-color:#ff8299;box-shadow:0 0 0 2px #ff829955,0 0 14px #ff416e,0 0 26px #ff416e66;}
.game-screen .table-side-label.is-active .player-status,.game-screen .table-side-label.is-active .player-status strong,.game-screen .table-side-label.is-active .throw-count{font-weight:800!important;color:inherit!important;text-shadow:inherit!important;background:transparent!important;-webkit-text-fill-color:currentColor!important;}
.game-screen .table-side-label.player-bottom.is-active .player-status,.game-screen .table-side-label.player-bottom.is-active .player-status strong,.game-screen .table-side-label.player-bottom.is-active .throw-count{color:#7dc8ff!important;text-shadow:0 0 7px #319dff,0 0 17px #319dff,0 0 28px #319dff88!important;}
.game-screen .table-side-label.player-top.is-active .player-status,.game-screen .table-side-label.player-top.is-active .player-status strong,.game-screen .table-side-label.player-top.is-active .throw-count{color:#ff8ca1!important;text-shadow:0 0 7px #ff426c,0 0 17px #ff426c,0 0 28px #ff426c88!important;}
@media(max-width:650px){
 .game-screen .matchstack{--cup-scale:clamp(.86,calc((100vw - 20px)/300px),1.32);height:calc(100dvh - 8px);min-height:0;}
 .game-screen .matchstack .cupfield{height:auto!important;min-height:0!important;flex:1 1 0;}
 .game-screen .table-side-label{min-height:64px;}
}
@media(max-width:360px){.game-screen .matchstack{--cup-scale:clamp(.8,calc((100vw - 20px)/310px),1.1);}}
@media(max-height:700px) and (max-width:650px){.game-screen .matchstack .cupfield{height:auto!important;min-height:0!important;}}

/* V3.7: only status text glows; never a rectangular highlight. */
.game-screen .table-side-label.is-active .player-status,.game-screen .table-side-label.is-active .player-status strong,.game-screen .table-side-label.is-active .throw-count{background:none!important;box-shadow:none!important;filter:none!important;outline:0!important;}
.game-screen .table-side-label.is-active .player-status strong{display:inline!important;padding:0!important;border:0!important;border-radius:0!important;}
/* Trickshot flash catches and dismisses the next tap; it must not register a throw. */
.trick-flash{pointer-events:auto!important;cursor:pointer;touch-action:manipulation;}
/* Profile pictures in the online ranking and individual statistics. */
.compact-stats td .btn{display:inline-flex;align-items:center;gap:8px;text-align:left;}
.compact-stats td .avatar{width:33px;height:33px;flex:none;}
.player-stats-heading{display:flex;align-items:center;gap:10px;}
.player-stats-heading .avatar{width:48px;height:48px;}


/* V3.8 – Neon nur auf den Buchstaben, niemals auf dem Namensbereich. */
.game-screen .table-side-label.is-active,
.game-screen .table-side-label.is-active .player-label,
.game-screen .table-side-label.is-active .player-status {
  text-shadow:none!important;
  box-shadow:none!important;
  filter:none!important;
  background:transparent!important;
  outline:none!important;
}
.game-screen .table-side-label.is-active .player-status strong,
.game-screen .table-side-label.is-active .throw-count {
  display:inline!important;
  background:transparent!important;
  border:0!important;
  outline:0!important;
  box-shadow:none!important;
  filter:none!important;
  padding:0!important;
}
.game-screen .table-side-label.player-top.is-active .player-status strong,
.game-screen .table-side-label.player-top.is-active .throw-count {
