/* V4.2: Einheitliche Hinweise und Bestätigungen statt Browser-Pop-ups. */
.app-dialog-backdrop{position:fixed;inset:0;z-index:250;display:grid;place-items:center;background:#06131de0;padding:16px;}
.app-dialog-card{width:min(440px,100%);border:2px solid #83b7dc;border-radius:20px;background:linear-gradient(150deg,#203a4d,#101e2d);box-shadow:0 0 35px #319dff44,0 24px 65px #000b;text-align:center;padding:24px 20px;color:#f4f6f8;}
.app-dialog-icon{font-size:38px;margin-bottom:8px;}
