/* V4.5 – Online-Spielerprofile */
.profile-directory{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:12px;margin:16px 0}
.profile-list-card{display:flex;align-items:center;gap:14px;width:100%;padding:16px;background:#1b2b36;border:1px solid #334854;border-radius:16px;color:#f4f6f8;text-align:left}
