.profile-zoom-overlay{position:fixed;inset:0;z-index:9999;background:#000e;display:flex;align-items:center;justify-content:center;padding:30px}
.profile-zoom-overlay img{max-width:95vw;max-height:85vh;object-fit:contain;border-radius:12px}
.profile-zoom-close{position:absolute;right:18px;top:15px;color:#fff;background:#304651;border-radius:50%;width:44px;height:44px;font-size:22px}
.profile-zoom-placeholder{font-size:100px;font-weight:900}

/* V4.6 – kompakte Navigation und aufgeräumte Spielerprofile */
.top{align-items:flex-start}
.top-actions{display:flex;flex-direction:column;align-items:stretch;gap:7px;flex-shrink:0}
