@media(max-width:650px){.top .brand{font-size:clamp(20px,5.5vw,28px);line-height:1.2;padding-top:5px;min-width:0}.top-actions .btn{padding:9px 10px;font-size:13px;min-width:105px}}
.profile-status{text-align:center;margin:12px 0 18px;padding:12px 14px}
