.profile-edit-buttons{display:flex;justify-content:center;gap:10px;flex-wrap:wrap;margin-top:15px}
.profile-status-editor textarea{width:100%;box-sizing:border-box;background:#101e27;color:#fff;border:1px solid #49606c;border-radius:11px;padding:12px;font:inherit;resize:vertical;margin:10px 0 18px}

/* V4.7: Mobile-Kopfbereich und reduzierte Spielerstatistik */
.top .brand{display:flex;align-items:flex-start;gap:5px;line-height:1.1;}
.top .brand-lines{display:flex;flex-direction:column;align-items:flex-start;gap:2px;color:#f4f6f8;}
