.top .brand-lines .brand-accent{color:#ffb84d;}
.top-actions .btn{padding:12px 16px;min-width:124px;font-size:16px;}
@media(max-width:650px){.top .brand{font-size:clamp(19px,5vw,27px);letter-spacing:-.7px;}.top-actions .btn{padding:12px 12px;min-width:116px;font-size:15px;}}
.compact-stats td .stats-player-link{display:inline-flex;align-items:center;gap:8px;background:transparent!important;border:0!important;box-shadow:none!important;color:#f4f6f8;font-weight:750;text-align:left;padding:0!important;margin:0;max-width:100%;min-width:0;font-size:inherit;}
.compact-stats td .stats-player-link span:last-child{min-width:0;overflow-wrap:anywhere;}
