.top .brand-lines{min-width:0;}
@media(max-width:650px){
  .top{gap:8px;}
  .top .brand{font-size:clamp(32px, 9.4vw, 46px);letter-spacing:-1.4px;line-height:1.02;padding-top:3px;}
