  .top .brand{font-size:clamp(37px,10.7vw,46px);letter-spacing:-1.7px;}
}
/* Island: nur bei einem wirklich alleinstehenden gegnerischen Becher aktiv. */
.game-actions .island-action:disabled{opacity:.33;filter:grayscale(1);cursor:not-allowed;}
