/* King-of-the-Table-Vorschau für reguläre Spieler */
.kot-locked{opacity:.46;filter:grayscale(.8);cursor:not-allowed!important;pointer-events:none;}

/* Live-Matchstatistik: rechte Lasche und wiederverwendete Endstatistik */
.matchstack .live-stats-tab{position:absolute;right:5px;top:50%;transform:translateY(-50%);z-index:15;writing-mode:vertical-rl;transform-origin:center;letter-spacing:1.5px;font-size:12px;font-weight:800;color:#d6f0ff;background:linear-gradient(135deg,#284e6d,#19334c);border:1px solid #6698bd;border-radius:11px;padding:15px 9px;min-height:112px;box-shadow:0 0 13px #3c9ad655;cursor:pointer;touch-action:manipulation}
.matchstack .live-stats-tab:active{background:#3b7299;box-shadow:0 0 22px #65caffaa}
.live-stats-backdrop{position:fixed;inset:0;z-index:1200;background:#07111bd9;display:flex;align-items:center;justify-content:center;padding:12px;box-sizing:border-box}
.live-stats-dialog{width:min(100%,560px);max-height:min(92dvh,850px);background:#172b40;border:1px solid #52718d;border-radius:18px;box-shadow:0 20px 70px #000b;display:flex;flex-direction:column;overflow:hidden;color:#f4f8fc}
