.live-stats-badge{display:inline-flex;align-items:center;gap:6px;color:#bbf7d0;background:#166534;border:1px solid #22c55e;border-radius:30px;padding:5px 10px;font-size:11px;font-weight:900;letter-spacing:1px}
.live-stats-dot{width:7px;height:7px;border-radius:50%;background:#86efac;box-shadow:0 0 8px #86efac}
.live-stats-close{background:#29465f;border:1px solid #688da9;border-radius:50%;width:34px;height:34px;color:white;font-size:19px;cursor:pointer;flex-shrink:0}
.live-stats-scroll{overflow:auto;overscroll-behavior:contain;padding:8px 10px 14px}
.live-stats-table{width:100%;table-layout:fixed;text-align:center;margin:0}
.live-stats-table th{width:30%;overflow-wrap:anywhere;vertical-align:middle}
.live-stats-table th:nth-child(2){width:40%}
.live-stats-table th .avatar{vertical-align:middle;margin-right:4px}
